    private bool ConfirmStorage(string title,string text,string token)
    {var dialog=BrandedDialog.CreateConsent(this,title,text+"\n\nДля подтверждения введи: "+token,"Я проверил цель и сохранил нужные данные. Последствия понятны.","Применить");var typed=new TextBox{Margin=new Thickness(0,10,0,0)};dialog.Body.Children.Add(typed);void Gate()=>dialog.AcceptButton.IsEnabled=typed.Text==token&&dialog.Consent!.IsChecked==true;typed.TextChanged+=(_,_)=>Gate();dialog.Consent!.Checked+=(_,_)=>Gate();Gate();return dialog.ShowDialog()==true;}
    private async Task ApplyStorage(Dictionary<string,object?> request)
    {
        if(!CanUpdate)return;storageBusy=true;storageWrite=StorageBackend.Writes((string)request["action"]!);storageClock.Restart();Activity.Text="Windows выполняет операцию диска. Не отключайте накопитель и питание.";
        try{var result=await StorageBackend.Run(request);Activity.Text="Операция завершена · результат записан в локальный журнал";string details="Windows подтвердила завершение выбранной операции.";if(result.TryGetProperty("backup",out var backup))details+="\n\nКопия: "+backup.GetString();BrandedDialog.Notify(this,"Операция завершена",details);if(storageMode=="boot")bootData=await StorageBackend.Run(StorageBackend.Request("boot_inventory"));else{int? number=selectedDisk?.Number;storage=await StorageBackend.Read();selectedDisk=storage.Disks.FirstOrDefault(d=>d.Number==number);efiData=null;}}
        catch(Exception ex){Activity.Text="Операция не подтверждена · проверь журнал и обнови состояние";BrandedDialog.Notify(this,"Операция не подтверждена",ex.Message+"\n\nНе повторяй действие вслепую: сначала обнови состояние диска.");}
        finally{storageClock.Stop();storageBusy=false;storageWrite=false;if(current=="storage")ShowPage("storage");}
    }
    private void EfiPage(Grid host,StorageDisk disk)
