        var note=Txt("Microsoft и Boot защищены. Используемость остальных каталогов не определяется автоматически. До удаления создаётся ZIP-копия с проверкой SHA-256; удаление активного загрузчика может нарушить загрузку.",12,"#FFBF7F",new Thickness(0,0,0,12));AddRow(panel,note,1);var list=new ListBox{Margin=new Thickness(0,0,0,12)};AddRow(panel,list,2);
        if(efiData.HasValue)foreach(var folder in efiData.Value.GetProperty("folders").EnumerateArray())list.Items.Add(new ListBoxItem{Content=$"{folder.GetProperty("name").GetString()} · {StorageBackend.Size(folder.GetProperty("bytes").GetUInt64())} · {folder.GetProperty("files").GetInt32()} файлов"+(folder.GetProperty("protected").GetBoolean()?" · защищён":""),Tag=folder.Clone()});
        var actions=new WrapPanel();var inspect=Action("Прочитать EFI",async()=>{if(selector.SelectedItem is not StoragePartition part||!CanUpdate)return;storageBusy=true;try{efiData=await StorageBackend.Run(StorageBackend.Request("efi_inventory",disk,part));efiPartition=part.Number;efiDiskKey=disk.Key;}catch(Exception ex){BrandedDialog.Notify(this,"EFI не прочитан",ex.Message);}finally{storageBusy=false;if(current=="storage")ShowPage("storage");}});inspect.IsEnabled=selector.Items.Count>0&&CanUpdate;actions.Children.Add(inspect);
        var remove=Action("Удалить выбранный каталог",async()=>{if(selector.SelectedItem is not StoragePartition part||list.SelectedItem is not ListBoxItem item||item.Tag is not JsonElement folder)return;if(efiPartition!=part.Number||efiDiskKey!=disk.Key)return;if(folder.GetProperty("protected").GetBoolean()){Activity.Text="Этот каталог защищён";return;}string name=folder.GetProperty("name").GetString()!;if(!ConfirmStorage("Очистка EFI",disk.Description+"\n"+part.Description+"\nКаталог EFI\\"+name+"\n\nПеред удалением будет проверена резервная копия. Удаление используемого загрузчика может сделать ПК незагружаемым.",name))return;var request=StorageBackend.Request("efi_cleanup",disk,part);request["folder"]=name;request["folder_key"]=folder.GetProperty("key").GetString();await ApplyStorage(request);});remove.IsEnabled=CanUpdate&&efiData.HasValue;actions.Children.Add(remove);AddRow(panel,actions,3);selector.SelectionChanged+=(_,_)=>{efiData=null;list.Items.Clear();};
    }
